// Test-only registry fixtures. The proofs come from the committed Groth16
// fixture (contracts/shared/fixtures/groth16_fixture.rs, generated by
// scripts/vk-to-soroban.ts from the committed proving key), the same bytes the
// contract tests verify on Soroban, so the browser verifier is tested against
// real on-chain data rather than a proof made up for the test.

import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type { RegistryDetailResponse, RegistryListResponse, RegistryNote } from "@/lib/types/api";
import type { SnarkjsVerificationKey } from "@/lib/zk/format";
import { sorobanToProof } from "@/lib/zk/format";

import { HIDDEN_FIELDS } from "../trust-content";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(HERE, "../../../../..");
export const RUST_FIXTURE = path.join(REPO, "contracts/shared/fixtures/groth16_fixture.rs");
/** The key the app serves at /zk/verification_key.json. */
export const SERVED_VK = path.join(REPO, "apps/web/public/zk/verification_key.json");

export function loadServedVerificationKey(): SnarkjsVerificationKey {
  return JSON.parse(readFileSync(SERVED_VK, "utf8")) as SnarkjsVerificationKey;
}

export interface FixtureNote {
  agent: string;
  totalCommissionCents: bigint;
  agentCommissionCents: bigint;
  escrituraDay: number;
  commitment: string;
  nullifier: string;
  /** Hex as stored on-chain (A negated). */
  proof: { a: string; b: string; c: string };
  publicInputs: string[];
}

const hexOf = (body: string) =>
  [...body.matchAll(/0x([0-9a-fA-F]{2})/g)].map((m) => m[1].toLowerCase()).join("");

/** The bracketed text after `name: [` (balanced). */
function bracketed(block: string, name: string): string {
  const m = new RegExp(`\\b${name}: \\[`).exec(block);
  if (!m) throw new Error(`fixture field ${name} not found`);
  const open = m.index + m[0].length - 1;
  let depth = 0;
  for (let i = open; i < block.length; i++) {
    if (block[i] === "[") depth++;
    if (block[i] === "]" && --depth === 0) return block.slice(open + 1, i);
  }
  throw new Error(`fixture field ${name} is not closed`);
}

function scalar(block: string, name: string): string {
  const m = new RegExp(`\\b${name}: "?([^",\\n]+)"?,`).exec(block);
  if (!m) throw new Error(`fixture field ${name} not found`);
  return m[1].trim();
}

let cached: FixtureNote[] | undefined;

/** The three proved notes of the Rust fixture (two for agent A, one for agent B). */
export function fixtureNotes(): FixtureNote[] {
  if (cached) return cached;
  const source = readFileSync(RUST_FIXTURE, "utf8");
  const list = source.slice(source.indexOf("pub const NOTES"));
  const blocks = list.split("FixtureNote {").slice(1);
  cached = blocks.map((block) => {
    const inputs = bracketed(block, "public_inputs");
    return {
      agent: scalar(block, "agent"),
      totalCommissionCents: BigInt(scalar(block, "total_commission_cents")),
      agentCommissionCents: BigInt(scalar(block, "agent_commission_cents")),
      escrituraDay: Number(scalar(block, "escritura_day")),
      commitment: hexOf(bracketed(block, "commitment")),
      nullifier: hexOf(bracketed(block, "nullifier")),
      proof: { a: hexOf(bracketed(block, "a")), b: hexOf(bracketed(block, "b")), c: hexOf(bracketed(block, "c")) },
      publicInputs: inputs
        .split("]")
        .map(hexOf)
        .filter((h) => h.length === 64)
        .map((h) => BigInt(`0x${h}`).toString()),
    };
  });
  return cached;
}

const MINT_TX = "7b1e5f0a9c3d4e2f8a6b0c1d2e3f405162738495a6b7c8d9e0f1a2b3c4d5e6f7";
const DAY = 86_400;

/** A registry list row for a fixture note (amounts converted to stroops like cpcv_note stores them). */
export function registryNote(n: FixtureNote, id: number, overrides: Partial<RegistryNote> = {}): RegistryNote {
  const total = n.totalCommissionCents * 100_000n;
  const agent = n.agentCommissionCents * 100_000n;
  return {
    id,
    agent: n.agent,
    totalCommission: total.toString(),
    agentCommission: agent.toString(),
    exploradorCommission: (total - agent).toString(),
    creditLimit: (agent / 2n).toString(),
    escrituraDay: n.escrituraDay,
    status: "Active",
    overdue: false,
    mintedAt: (n.escrituraDay - 90) * DAY + 15 * 3600,
    mintTxHash: MINT_TX,
    ...overrides,
  };
}

/** GET /api/registry/[id] for the worked-example fixture note, with a realistic timeline. */
export function detailResponse(index = 0, id = 1, overrides: Partial<RegistryNote> = {}): RegistryDetailResponse {
  const n = fixtureNotes()[index];
  const row = registryNote(n, id, overrides);
  const minted = row.mintedAt;
  return {
    note: { ...row, commitment: n.commitment, nullifier: n.nullifier, proof: n.proof },
    publicSignals: n.publicInputs,
    snarkjsProof: sorobanToProof(n.proof),
    draws: { count: 2, total: "30000000000" },
    timeline: [
      { type: "NoteMinted", at: minted, ledger: 1_204_511, txHash: MINT_TX, data: { id, agent: n.agent, totalCommission: row.totalCommission } },
      { type: "LineOpened", at: minted, ledger: 1_204_511, txHash: MINT_TX, data: { noteId: id, agent: n.agent, creditLimit: row.creditLimit } },
      {
        type: "CardDraw",
        at: minted + 2 * 3600,
        ledger: 1_206_002,
        txHash: "a4b3c2d1e0f9a8b7c6d5e4f3a2b1c0d9e8f7a6b5c4d3e2f1a0b9c8d7e6f5a4b3",
        data: { agent: n.agent, amount: "3490000000", fromBalance: "0", fromCredit: "3490000000", attributedToNote: "3490000000" },
      },
      {
        type: "CardDraw",
        at: minted + 5 * 3600,
        ledger: 1_206_950,
        txHash: "5c6d7e8f9a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d",
        data: { agent: n.agent, amount: "26510000000", fromBalance: "0", fromCredit: "26510000000", attributedToNote: "26510000000" },
      },
    ],
    hidden: [...HIDDEN_FIELDS],
  };
}

/** GET /api/registry: the fixture notes plus a few more statuses. */
export function listResponse(): RegistryListResponse {
  const [a, b, c] = fixtureNotes();
  const notes: RegistryNote[] = [
    registryNote(c, 5, { status: "WrittenOff", mintTxHash: null }),
    registryNote(b, 4, { status: "Cancelled" }),
    registryNote(a, 3, { status: "Settled" }),
    registryNote(b, 2, { overdue: true }),
    registryNote(a, 1),
  ];
  return { notes, nextCursor: null, counts: { Active: 2, Settled: 1, Cancelled: 1, WrittenOff: 1, total: 5 } };
}
